"use client"

import * as React from "react"

import { type FileRef, type ViewerAdapter } from "@/lib/retab"
import { cn } from "@/lib/utils"
import { useDocumentUrl } from "@/hooks/use-retab"
import { DocumentSurface } from "@/components/ui/document-surface"

export interface RetabSourcePreviewProps {
  adapter?: ViewerAdapter
  file?: FileRef
  className?: string
}

/**
 * Resolves a source document through the adapter and renders it. Shows nothing
 * if the adapter can't resolve a URL, so it's safe to drop into any viewer.
 */
export function RetabSourcePreview({
  adapter,
  file,
  className,
}: RetabSourcePreviewProps) {
  const { data: url, loading, error } = useDocumentUrl(adapter, file)

  if (!adapter?.getDocumentUrl || !file) return null

  if (loading) {
    return (
      <div
        className={cn(
          "flex min-h-24 items-center justify-center rounded-md border bg-muted text-xs text-muted-foreground",
          className
        )}
      >
        Loading source…
      </div>
    )
  }

  if (error || !url) {
    return (
      <div
        className={cn(
          "flex min-h-24 items-center justify-center rounded-md border bg-muted text-xs text-muted-foreground",
          className
        )}
      >
        {error ? "Couldn't load source document." : "No source available."}
      </div>
    )
  }

  return (
    <DocumentSurface
      url={url}
      mimeType={file.mime_type}
      title={file.filename}
      className={cn("h-80", className)}
    />
  )
}
